def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def assignments(raw):
    result={}
    for node in ast.parse(raw).body:
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name):
            if node.targets[0].id in ('SCHEMA','SOURCE_PINS','DRIVER_SHA','ROOT_SNAPSHOT_SCHEMA','ROOT_SNAPSHOT_KEYS'):
                result[node.targets[0].id]=ast.literal_eval(node.value)
    return result

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,required=True)
    parser.add_argument('--outdir',type=Path,required=True)
    parser.add_argument('--lower-directory',type=Path,required=True)
    args=parser.parse_args()
    repo=args.repo.resolve();out=args.outdir.resolve();lower=args.lower_directory.resolve()
    if (out==repo or repo in out.parents or out==lower or out in lower.parents
            or out.exists()):
        raise ValueError('Use one new separate source-only output directory')
    generated={};parent_records=[]
    for plan in PLANS:
        parent=repo/plan['parent'];raw=parent.read_bytes()
        if len(raw)!=plan['parent_bytes'] or digest(raw)!=plan['parent_sha256']:
            raise ValueError('The complete immutable scientific parent differs: '+str(parent))
        text=raw.decode('utf-8')
        for patch in plan['patches']:
            if text.count(patch['old'])!=patch['count']:
                raise ValueError('An entire exact textual replacement does not match')
            text=text.replace(patch['old'],patch['new'])
        value=text.encode()
        if len(value)!=plan['bytes'] or digest(value)!=plan['sha256'] or len(value)>=100000:
            raise ValueError('The whole explicitly declared output differs: '+plan['name'])
        tree=ast.parse(value,filename=plan['name'])
        compile(tree,plan['name'],'exec')
        for node in ast.walk(tree):
            if isinstance(node,ast.Dict):
                keys=[]
                for key in node.keys:
                    if isinstance(key,ast.Constant) and isinstance(key.value,(str,int,float)):
                        if key.value in keys:raise ValueError('Duplicate literal dictionary key')
                        keys.append(key.value)
        if any(line.rstrip()!=line for line in text.splitlines()):
            raise ValueError('Source trailing whitespace')
        generated[plan['name']]=value
        parent_records.append(dict(path=str(parent),bytes=len(raw),sha256=digest(raw)))
    driver=next(p for p in PLANS if p['role']=='driver')
    reader=next(p for p in PLANS if p['role']=='reader')
    launcher=next(p for p in PLANS if p['role']=='launcher')
    da=assignments(generated[driver['name']])
    for item in (reader,launcher):
        if assignments(generated[item['name']])['DRIVER_SHA']!=driver['sha256']:
            raise ValueError('The complete reader/launcher pins the wrong actual driver')
    ra=assignments(generated[reader['name']])
    if (ra['ROOT_SNAPSHOT_SCHEMA']!=da['ROOT_SNAPSHOT_SCHEMA']
            or ra['ROOT_SNAPSHOT_KEYS']!=da['ROOT_SNAPSHOT_KEYS']
            or len(da['ROOT_SNAPSHOT_KEYS'])!=38):
        raise ValueError('Keep all complete own-point root snapshots including closure provenance')
    all_roles={}
    for role,(relative,expected) in da['SOURCE_PINS'].items():
        filename=Path(relative).name
        if filename in generated:
            raw=generated[filename];origin='whole derived upper source'
        elif (lower/filename).is_file():
            raw=(lower/filename).read_bytes();origin=str(lower/filename)
        else:
            raw=(repo/'topics/visible-flex-larger-amplitude'/relative).read_bytes()
            origin=str(repo/'topics/visible-flex-larger-amplitude'/relative)
        if digest(raw)!=expected:raise ValueError('The entire actual source role changed: '+role)
        all_roles[role]=dict(path=origin,sha256=expected,bytes=len(raw))
    for record in parent_records:
        raw=Path(record['path']).read_bytes()
        if len(raw)!=record['bytes'] or digest(raw)!=record['sha256']:
            raise ValueError('A whole source parent changed during reproduction')
    out.mkdir(parents=True)
    for name,raw in generated.items():
        with (out/name).open('xb') as stream:stream.write(raw)
    manifest=dict(schema=SCHEMA,source_sha256=digest(Path(__file__).read_bytes()),
        parents=parent_records,whole_output_sources=[
            {k:p[k] for k in ('role','name','sha256','bytes')} for p in PLANS],
        complete_actual_source_roles=all_roles,
        source_only_AST_and_compile_without_import=True,
        scientific_source_imports_or_F_J_roots_or_fixtures_executed=False)
    (out/'source-only-reproduction.json').write_text(
        json.dumps(manifest,sort_keys=True,indent=2,allow_nan=False)+'\n')
    print(json.dumps(dict(schema=SCHEMA,complete=True,whole_source_outputs=len(generated),
        complete_source_roles=len(all_roles),scientific_evaluations=0),sort_keys=True))

if __name__=='__main__':
    main()
